"""Small public reproduction: actual SQL effects, no model calls or network.

Needs pinned execution_gate.py, additive_budget.py and make_statefix.py in this
folder (or the original in upstream/). Does not write files or alter the original.
"""
from fractions import Fraction as F
from pathlib import Path
from types import ModuleType
import json
import sys
from additive_budget import AdditiveBudget
from make_statefix import derive,OLD
from hashlib import sha256

ROOT=Path(__file__).resolve().parent
source=ROOT/'upstream'/'execution_gate.py'
if not source.exists():source=ROOT/'execution_gate.py'
data=source.read_bytes()
if sha256(data).hexdigest()!=OLD:raise ValueError('Original identity mismatch')


def module(raw,name):
    m=ModuleType(name)
    exec(compile(raw,name,'exec'),m.__dict__)
    return m


ORIGINAL=module(data,'original_gate')
FIXED=module(derive(data),'statefixed_gate')


def need(ok,why):
    if not ok:raise AssertionError(why)


def run_case(bounds,arm,fixed=False,aborts=0):
    impl=FIXED if fixed else ORIGINAL
    gate=impl.Gate(impl.ManualClock())
    additive=AdditiveBudget()
    unique=list(dict.fromkeys(bounds));leases={b:'L'+str(i) for i,b in enumerate(unique)}
    accepted=[];effects=[];error=None;refusals=[]
    try:
        for b,lid in leases.items():
            w=F(0) if arm=='A' else max(map(F,bounds)) if arm=='W' else F(b)
            gate.install(lid,'agent',str(w),1000,100)
        for i,b in enumerate(bounds,1):
            if arm=='A' and not additive.permits(b):
                refusals.append([i,'ADDITIVE_BUDGET']);continue
            try:
                out=impl.Client(gate,'agent').send({'op':'prepare','lease':leases[b],'action':'WORK1'})
            except ValueError as exc:
                error={'at':i,'message':str(exc),'q_chars':len(gate.get('q'))};break
            if out['status']!='PREPARED':refusals.append([i,out['reason']]);continue
            if arm=='A':need(additive.reserve(b),'Sequential additive mismatch')
            accepted.append(i)
            end=impl.Client(gate,'agent').send({'op':'abort' if i<=aborts else 'commit','ticket':out['ticket']})
            if end['status']=='COMMITTED':effects.append(i)
        need(len(gate.export()['effects'])==len(effects),'Actual SQL effects differ')
    finally:gate.close()
    return {'accepted_ids':accepted,'effect_ids':effects,'error':error,'refusals':refusals}


def run():
    specs={'homogeneous-10':['1/100']*10,'homogeneous-11':['1/100']*11,
           'low-30':['1/500']*30,'high-10':['1/25']*10,
           'alternating-20':['1/500','1/25']*10,'abort-exhaustion':['1/100']*11,
           'peer-02':['1/50']*10,'peer-10':['1/10']*3,
           'granularity-051':['51/1000']*2,
           'high-before-low':['51/1000']*2+['1/500']*24,
           'low-before-high':['1/500']*24+['51/1000']*2,
           'small-001':['1/1000']*110}
    rows={k:{a:run_case(bs,a,aborts=10 if k=='abort-exhaustion' else 0)
             for a in ('A','R','W')} for k,bs in specs.items()}
    for name in list(specs)[:6]:
        need(rows[name]['A']['accepted_ids']==rows[name]['R']['accepted_ids'],'Original workload mismatch')
    need(len(rows['high-before-low']['A']['effect_ids'])==25
         and len(rows['high-before-low']['R']['effect_ids'])==2,'Order counterexample')
    for a in ('R','W'):
        need(rows['small-001'][a]['error']=={'at':28,'message':'NUMBER_TOO_LONG','q_chars':164},'Original resource defect')
    repaired={a:run_case(specs['small-001'],a,fixed=True) for a in ('A','R','W')}
    need(all(v['error'] is None for v in repaired.values()),'Fixed kernel error')
    need({a:len(v['effect_ids']) for a,v in repaired.items()}=={'A':100,'R':105,'W':105},'Fixed small workload')
    low31=run_case(['1/500']*31,'R')
    need(low31['error']=={'at':31,'message':'NUMBER_TOO_LONG','q_chars':163},'Second boundary')
    return {'artifact':'AH004-BASELINE-DECISION-v1','status':'PASS','cases':rows,
            'repaired_small_001':repaired,'original_low31':low31,
            'limits':'Author-controlled public SQL workload; supplied risk labels, no realistic task or LLM trial.'}


if __name__=='__main__':
    print(json.dumps(run(),indent=2,sort_keys=True))
```

